"""Demo: tropical signatures classify statements across the multiverse.

Embeds each Boolean truth value into the tropical (min-plus) semiring
(true -> 0, false -> +inf), then reads existence off the tropical sum (min) and
universality off the tropical product (+). Independence shows the signature
(sum = 0, product = +inf).
"""
from __future__ import annotations
import math
from typing import Dict, List, Tuple

TROP_ZERO, TROP_ONE = math.inf, 0.0

def beta(b: bool) -> float:
    return TROP_ONE if b else TROP_ZERO

def trop_sum(vs: List[float]) -> float:
    acc = TROP_ZERO
    for v in vs:
        acc = min(acc, v)
    return acc

def trop_prod(vs: List[float]) -> float:
    acc = TROP_ONE
    for v in vs:
        acc = acc + v
    return acc

UNIVERSES = ["L", "Cohen", "Meas"]
HOLDS: Dict[str, Dict[str, bool]] = {
    "L":     {"ZFC": True,  "CH": True,  "V=L": True,  "LC": False},
    "Cohen": {"ZFC": True,  "CH": False, "V=L": False, "LC": False},
    "Meas":  {"ZFC": True,  "CH": True,  "V=L": False, "LC": True},
}

def signature(stmt: str) -> Tuple[float, float]:
    vals = [beta(HOLDS[u][stmt]) for u in UNIVERSES]
    return trop_sum(vals), trop_prod(vals)

def classify(stmt: str) -> str:
    s, p = signature(stmt)
    if s == TROP_ONE and p == TROP_ONE:
        return "multiverse-true"
    if s == TROP_ONE:
        return "independent"
    return "multiverse-false"

if __name__ == "__main__":
    for stmt in ["ZFC", "CH", "V=L", "LC"]:
        s, p = signature(stmt)
        fs = "+inf" if s == math.inf else f"{s:g}"
        fp = "+inf" if p == math.inf else f"{p:g}"
        print(f"{stmt:>4}: sum={fs:>5} prod={fp:>5} -> {classify(stmt)}")

