function TROPICAL_SIGNATURE(truths[0..n-1]):
    trop_sum  <- +inf        # additive unit of min-plus
    trop_prod <- 0           # multiplicative unit of min-plus
    for i in 0..n-1:
        v <- (0 if truths[i] else +inf)   # beta embedding
        trop_sum  <- min(trop_sum, v)     # tropical addition
        trop_prod <- trop_prod + v        # tropical multiplication
    return (trop_sum, trop_prod)

function CLASSIFY(truths):
    (s, p) <- TROPICAL_SIGNATURE(truths)
    if s = 0 and p = 0:   return "multiverse-true"
    if s = 0 and p = +inf: return "independent"
    return "multiverse-false"

function CHEAPEST_WITNESS(holds[0..n-1], cost[0..n-1]):
    best_cost <- +inf
    best_idx  <- NONE
    for i in 0..n-1:
        w <- (cost[i] if holds[i] else +inf)
        if w < best_cost:
            best_cost <- w
            best_idx  <- i
    return (best_cost, best_idx)   # best_cost = +inf  <=>  impossible

function TROPICAL_STAR(w[0..n-1][0..n-1]):
    d <- copy(w)
    for i in 0..n-1:
        d[i][i] <- min(d[i][i], 0)      # reflexive closure
    for k in 0..n-1:
        for i in 0..n-1:
            for j in 0..n-1:
                d[i][j] <- min(d[i][j], d[i][k] + d[k][j])
    return d
